"use client";

import { useState, useEffect } from "react";
import debounce from "lodash.debounce";
import { useSearchParams, useRouter } from "next/navigation";

interface SearchBarProps {
  basePath: string; // Dynamic base path for different pages
}

const SearchBar = ({ basePath }: SearchBarProps) => {
  const searchParams = useSearchParams();
  const router = useRouter();

  const searchQueryFromURL = searchParams.get("search") || "";
  const [searchQuery, setSearchQuery] = useState(searchQueryFromURL);

  // Debounced function to update the URL
  const updateSearchParams = debounce((search: string) => {
    const params = new URLSearchParams(searchParams.toString());

    if (search.trim() === "") {
      params.delete("search"); // Remove search param if empty
    } else {
      params.set("search", search);
    }
    params.delete("page"); // Reset to first page on search

    const newUrl = `${basePath}${params.toString() ? "?" + params.toString() : ""}`;
    router.push(newUrl);
  }, 500);

  // Trigger search when input changes
  useEffect(() => {
    updateSearchParams(searchQuery);
  }, [searchQuery]);

  return (
    <input
      type="text"
      placeholder="Search..."
      value={searchQuery}
      onChange={(e) => setSearchQuery(e.target.value)}
      className="border p-2 mb-4 w-full"
    />
  );
};

export default SearchBar;